{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection in AccountSearchController",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The searchKey parameter is concatenated into a SOQL query string without escaping, which can lead to SOQL injection.",
      "remediation": "Use String.escapeSingleQuotes or bind variables to prevent SOQL injection."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Missing CRUD and FLS enforcement",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4, 6",
      "explanation": "The class does not enforce CRUD and FLS permissions, allowing users to potentially read and update fields they shouldn't have access to.",
      "remediation": "Add WITH USER_MODE to SOQL queries and DML operations, and use Security.stripInaccessible to remove inaccessible fields from the result set."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Sharing rules not enforced",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "7",
      "explanation": "The class is declared 'without sharing', which ignores record-level sharing rules. It should be 'with sharing' or 'inherited sharing' to enforce sharing rules.",
      "remediation": "Change the class declaration to 'public with sharing class CaseHistoryController'."
    },
    {
      "category": "C2",
      "title": "FLS not enforced",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "7",
      "explanation": "The Security.stripInaccessible method is used to enforce field-level security, but Salesforce Code Analyzer reports that it can't verify that only sanitized data is used after the check.",
      "remediation": "Ensure that all data returned by the method is sanitized and cannot be used to bypass field-level security checks."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in permission set",
      "severity": "Medium",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions sections",
      "explanation": "The permission set grants 'ModifyAllData' and 'ViewAllData' permissions, which are excessive for a tier-1 support agent role.",
      "remediation": "Remove 'ModifyAllData' and 'ViewAllData' permissions from the permission set."
    }
  ]
}
